WITH payload AS (SELECT $archive_payload$[{"id":"ccfba11e-025a-566e-a595-db0fcccf92e4","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -الوقوف أمام مدرسة البنات و مضايقتهن -توجه التهمة بالتحرش -التعزير بالسجن و اجللد و اإلبعاد .","document_number":"33481272","case_number":"3329988","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/28","year":"1434","subject":"حترش -الوقوف أمام مدرسة البنات و مضايقتهن -توجه التهمة بالتحرش -التعزير بالسجن و اجللد و اإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 33481272 :‬تاريخه ‪1433/12/28 :‬هـ‬\n                            ‫رقم الدعوى‪3329988 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34281352:‬تاريخه‪1434/07/26:‬هـ‬\n\n\n       ‫حتــرش ‪ -‬الوقــوف أمــام مدرســة البنــات و مضايقتهــن ‪ -‬توجــه التهمــة‬\n                             ‫بالتحــرش ‪ -‬التعزيــر بالســجن و اجللــد و اإلبعــاد ‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم ( احفــظ عورتــك إال مــن زوجتــك‬\n       ‫أو مــا ملكــت مينيــك ) رواه أبــو داود و الترمــذي و صححــه األلبانــي ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه (وافــد) بالتحــرش بالفتيــات‬\n       ‫عــن طريــق إمســاك عضــوه الذكــري و إخراجــه ‪ ،‬حيــث تقــدم أحــد‬\n       ‫املواطنــن بشــكوى لــدى الشــرطة مفيــد ًا فيهــا عــن قيــام املدعــى عليــه‬\n       ‫أمــام مدرســة البنــات مبنــاداة البنــات وإخــراج لهــن عضــوه الذكــري‬\n       ‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه و احلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة ‪ ،‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n       ‫بواســطة مترجــم احملكمــة صــادق علــى دعــوى املدعــي العــام وأنكــر‬\n       ‫التحــرش جــرى الرجــوع إلــى محضــر الشــهادة املرفــق باملعاملــة ‪ .‬بنــاء‬\n       ‫علــى مــا تقــدم حكمــت احملكمــة بإثبــات إدانــة املدعــى عليــه بكشــف‬\n       ‫عورتــه و إظهــار عضــوه الذكــري و إمســاكه ‪ ،‬توجــه التهمــة لــه‬\n       ‫بالتحــرش بالفتيــات حــال فعلــه ذلــك وتعزيــره بالســجن أربعــة أشــهر‬\n\n‫‪79‬‬\n\f‫يحتســب منهــا مــا مضــى مــن توقيــف بســبب هــذه القضيــة وجلــده‬\n‫خمســن جلــده مكــرره علــى ثــاث مــرات والتوصيــة بإبعــاده ‪ ،‬قــرر‬\n‫وصــدق احلكــم‬ ‫املدعــى عليــه قناعتــه باحلكــم‪ ،‬لــم يقنــع املدعــي العــام ُ‬\n                                                  ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بينبــع‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بينبع‪/‬املســاعد برقــم ‪ ....‬وتاريــخ ‪ .....‬املقيــدة باحملكمــة برقم ‪ ....‬وتاريخ‬\n‫‪ .....‬ففــي يــوم الســبت املوافــق ‪ .....‬افتتحــت اجللســة الســاعة ‪00 : 00‬ص‬\n‫وفيهــا حضــر املدعــي العــام ‪ ....‬وادعــى قائــا بصفتــي مدعيــا عامــا يف‬\n‫دائــرة االدعــاء العــام مبحافظــة أدعــي علــى(‪ )........‬العمــر(‪ )....‬عامــا‬\n‫اجلنســية ‪ ....‬مبوجــب اإلقامــة رقــم (‪ )....‬قبــض عليه بتاريخ ‪ .....‬وأفرج عنه‬\n‫بالكفالــة احلضوريــة بتاريــخ ‪ .....‬حيــث أنــه بتاريــخ ‪.....‬تقــدم املدعــي إلــى‬\n‫مركــز الشــرطة بشــكوى مفيــدا فيهــا قيــام املدعــى عليــه أمــام مدرســة‬\n‫البنــات مبنــاداة البنــات ويخــرج لهــن عضــوه الذكــري بعــد أن قــام بإنزال‬\n‫بنطالــه إلــى حــد ركبتيــه وباســتجواب املدعــى عليــه أقــر مبســك عضــوه‬\n‫الذكــري ألنــه يعانــي مــن مــرض احلساســية ممــا يجعلــه كثيــر احلكــة‬\n‫وأنــه أيضــا قــام بإنــزال بنطالــه قليــا حتــى يتأكــد خــروج الــدم مــن‬\n‫عدمــه وبســماع أقــوال املدعــي أفــاد بــأن شــقيقته طالبــة تــدرس يف تلــك‬\n‫املدرســة وأنــه عنــد خروجهــا مــن املدرســة برفقــة إحــدى زميالتهــا ميــر‬\n‫املدعــى عليــه ويقــوم بالنــداء عليهمــا وميســك عضــوه الذكــري ويخرجــه‬\n\n                                                                                       ‫‪80‬‬\n\f     ‫مــن مالبســه فاجتــه إلــى تلــك املدرســة يف ذلــك اليــوم للتأكــد مــن صحــة‬\n     ‫أقــوال شــقيقته وبالفعــل شــاهد املدعــى عليــه يقــوم مبــا ذكــر فامســك‬\n     ‫بــه وســلمه للشــرطة وبالبحــث عــن ســوابقه اتضــح عــدم وجــود ســوابق‬\n     ‫مســجلة عليــه وانتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه‬\n     ‫بالتحــرش بالفتيــات عــن طريــق إمســاك عضــوه الذكــري وإخراجــه لهم‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة‪ :‬مــا جــاء يف أقــوال املدعــى عليــه بقيامــه‬\n     ‫مبســك عضــوه الذكــري وإنزالــه بنطالــه واملــدون علــى الصفحــة رقــم‬\n     ‫(‪).... - ....‬مــن ملــف التحقيــق املرفــق لفــة (‪ )....‬وحيــث إن مــا أقــدم عليــه‬\n     ‫املذكــور فعــل محــرم شــرعا لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بعقوبــة تعزيريــة رادعــة لــه وزاجــرة لغيــره (علمــا بــأن احلــق اخلــاص‬\n     ‫لــم ينتهــي ) هكــذا ادعــى ونظــر ًا لعــدم حضــور املدعــى عليــه رغــم طلبــه‬\n     ‫لــذا جــرى رفــع اجللســة إلحضــاره ويف جلســة أخــرى لــدي أنــا القاضــي‬\n     ‫باحملكمــة العامــة ( ‪ ) ....‬اخللــف لفضيلــة الشــيخ مبوجــب قــرار املجلــس‬\n     ‫األعلــى للقضــاء رقــم ‪ ....‬يف ‪ .....‬ففــي يــوم الثالثــاء املوافــق ‪ ..../..../....‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ .... : ....‬وفيهــا حضــر املدعــي العــام ولم يحضر‬\n     ‫املدعــى عليــه بالرغــم مــن أنــه جــرى الكتابــة ملديــر الشــرطة باخلطــاب‬\n     ‫رقــم (‪ )........‬وتاريــخ ‪ .... /.../...‬ه ـ بشــأن القبــض عليــه وإحضــاره ‪،‬‬\n     ‫كمــا جــرى أيضــا الكتابــة حملافظــة ( ‪ ) ....‬باخلطــاب رقــم ‪ ....‬وتاريــخ‬\n     ‫‪ .....‬لإلحاطــة وتكليــف مــن يلــزم إلحضــار املطلــوب ‪،‬ونظــر ًا لطــول مــدة‬\n     ‫مكــث املعاملــة يف احملكمــة لعــدم إمكانيــة حضــور املدعــى عليــه إلــى‬\n     ‫احملكمــة طــوال هــذه املــدة ممــا تســبب يف تأخــر القضيــة وزيــادة يف‬\n     ‫عــبء العمــل وتشــتيتا جلهــد العاملــن لــذا فقــد قــررت صــرف النظــر‬\n     ‫عــن دعــوى املدعــي العــام لعــدم حضــور املدعــى عليــه وأفهمــت املدعــي‬\n\n\n‫‪81‬‬\n\f‫العــام بأنــه علــى دعــواه متــى مــا حضــر املدعــى عليــه وبعــرض ذلــك عليــه‬\n‫قــرر اعتراضــه علــى احلكــم بــدون الئحــة وأمــرت برفعهــا حملكمــة‬\n‫االســتئناف لتدقيقــه حســب املتبــع وبــاهلل التوفيــق‪ .‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 0000/00/00‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم األحــد املوافــق ‪0000/0/0‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا جــرى االطــاع علــى املعاملــة بعــد ورودهــا مــن محكمــة‬\n‫االســتئناف برقــم ‪ ....‬بتاريــخ ‪0000/0/0‬ه ـ مرفقــا بهــا قــرار أصحــاب‬\n‫الفضيلــة رقــم ‪ ....‬وتاريــخ ‪0000/0/0‬ه ـ واملتضمــن مــا نــص احلاجــة منه‪:‬‬\n‫«وبدراســة القــرار وصــورة ضبطــه تقــررت إعادتهــا لفضيلــة حاكمهــا‬\n‫ملالحظــة أن مــا حكــم بــه فضيلتــه مــن صــرف النظــر عن دعــوى املدعي‬\n‫العــام محــل نظــر ألن صــرف النظــر يعنــي أن الدعــوى غيــر صحيحــة‬\n‫كمــا أننــا لــم جنــد بــأوراق املعاملــة مــا يــدل علــى طلــب املدعــى عليــه‬\n‫مــن خطــاب طلــب إحضــار أو غيــره ولعــل الصــواب هــو إعــادة املعاملــة‬\n‫للجهــات املختصــة إلحضــار املدعــى عليــه رفــق أوراق املعاملــة ملالحظــة‬\n‫مــا ذكــر وإجــراء مــا يلــزم نحــو مــا أشــير إليــه واهلل املوفــق ‪ .‬قاضــي‬\n‫اســتئناف ‪ ....‬ختمــه وتوقيعــه وقاضــي اســتئناف ‪ ....‬ختمــه وتوقيعــه رئيس‬\n‫الدائــرة ‪ ....‬ختمــه وتوقيعــه» ‪ ،‬وعليــه أجيــب أصحــاب الفضيلــة وفقنــي‬\n‫اهلل وإياهــم إلــى كل خيــر ولوجاهــة مــا ذكــروه فقــد قــررت العــدول‬\n‫عمــا أجريــت ســابق ًا وأرجــأت النظــر يف احلكــم علــى املدعــى عليــه‬\n‫إلــى حــن إحضــاره وأمــرت بإعــادة كامــل أوراق املعاملــة إلــى شــرطة‬\n‫محافظــة ينبــع إلحضــار املدعــى عليــه رفــق املعاملــة ‪ .‬ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام واملدعــى عليــه اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم ‪ ....‬وجــرى عــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة‬\n\n\n                                                                                     ‫‪82‬‬\n\f     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه‬   ‫مترجــم احملكمــة فأجــاب قائ ـ ً‬\n     ‫كلــه صحيــح إال اتهامــي بالتحــرش بالفتيــات ومناداتهــن عندمــا أنزلــت‬\n     ‫بنطالــي فلــم أشــاهدهن حينهــا ‪ ،‬وقــد فعلــت ذلــك بســبب معاناتــي مــن‬\n     ‫احلساســية يف جســدي هكــذا قــال ‪ ،‬ثــم جــرى ســؤال املدعــي العــام‬\n     ‫عــن البينــة علــى دعــواه فقــال ‪ :‬إن بينتــي هــي مــا تضمنتــه أوراق املعاملــة‬\n     ‫هكــذا قــال ‪ ،‬وبالرجــوع إلــى املعاملــة تبــن أن أدلــة املدعــي العــام هــي‬\n     ‫مــا جــاء يف أقــوال املدعــى عليــه املدونــة ص ‪ 0-0‬لفــة (‪ )0‬وبالرجــوع إليهــا‬\n     ‫تبــن فيهــا إقــراره مبــا نســب إليــه دون فعلــه لذلــك أمــام البنــات ‪ ،‬كمــا‬\n     ‫جــرى االطــاع علــى أقــوال الشــاهد (‪ )........‬املدونــة علــى ص ‪ 0‬لفــة (‪)0‬‬\n     ‫مــن الدعــوى ولطلــب الشــاهد املذكــور رفعــت اجللســة ‪ .‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه ‪ ،‬وبســؤال املدعــي العــام عــن‬\n     ‫بينتــه وهــي الشــاهد املذكــور؟ فقــال‪ :‬لــم يحضــر وأطلــب مهلــة أخــرى‬\n     ‫إلحضــاره يف اجللســة القادمــة ‪ ،‬فأجيــب لطلبــه ‪ .‬ويف جلســة أخــرى حضر‬\n     ‫املدعــي العــام واملدعــى عليــه ‪ ،‬وبســؤال املدعــي العــام عــن بينتــه وهــي‬\n     ‫الشــاهد املذكــور؟ فقــال‪ :‬لــم يحضــر وأطلــب مهلــة أخــرى إلحضــاره‬\n     ‫يف اجللســة القادمــة ‪ ،‬فأجيــب لطلبــه وأفهــم بأنهــا املهلــة األخيــرة ‪ .‬ويف‬\n     ‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وجــرى ســؤال املدعــي‬\n     ‫العــام عــن الشــاهد املذكــور ؟ فقــال ‪ :‬إنــي لــم أمتكــن مــن إحضــاره‬\n     ‫‪ ،‬وعليــه فقــد اعتبرتــه عاجــزا عــن ذلــك ‪ ،‬ولدراســة القضيــة رفعــت‬\n     ‫اجللســة ‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام ومترجــم احملكمــة‬\n     ‫وبعــد ســماع دعــوى املدعــي العــام وإجابــة املدعــى عليــه ‪ ،‬وبعــد اإلطــاع‬\n     ‫علــى أوراق املعاملــة وأدلــة املدعــي العــام ‪ ،‬ونظــر ًا إلقــرار املدعــى عليــه‬\n     ‫مبــا نســبه إليــه املدعــي العــام مــن إخراجــه لعضــوه الذكــري وإمســاكه‬\n\n\n‫‪83‬‬\n\f‫بــه ‪ ،‬وإنــكاره التحــرش بالفتيــات أو مناداتهــن وبعــد اإلطــاع علــى‬\n‫الشــهادة املدونــة ص‪ 4‬لفــة ‪ 8‬مــن املعاملــة املتضمنــة ‪ ( :‬شــاهدت املدعــو‬\n‫‪ ....‬يتتبــع البنــات أثنــاء خروجهــن مــن املدرســة ويدخــل بــن الســيارات‬\n‫الواقفــة ويقــوم بإنــزال بنطالــه وميســك عضــوه الذكــري ويشــير إلــى‬\n‫البنــات ملناداتهــن بقصــد االنتبــاه إليــه فقمــت باإلمســاك بــه ) أ‪ .‬ه ـ لذلــك‬\n‫وملــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه بكشــف عورتــه وإظهــار‬\n‫عضــوه وإمســاكه ‪ ،‬وتوجــه التهمــة لــه بالتحــرش بالفتيــات حــال فعلــه‬\n‫ذاك ‪ ،‬ونظــر ًا ألن مــا قــام بــه املدعــى عليــه فعــل محــرم ومنكــر ‪ ،‬وفيــه‬\n‫إســاءة إلــى العفــة والفضيلــة وتعــدٍ وجــرأة علــى احلرمــات وألن مــا دفــع‬\n‫بــه املدعــى عليــه مــن إصابتــه (باحلكــة) ال يســوغ لــه كشــف عورتــه‬\n‫مبشــهد مــن النــاس ‪ ،‬ولقــول النبــي صلــى اهلل عليــه وســلم ‪ ( :‬احفــظ‬\n‫عورتــك إال مــن زوجتــك أو مــا ملكــت ميينــك ) رواه أبــو داود والترمــذي‬\n‫وصححــه األلبانــي ‪ ،‬لذلــك فقــد قــررت تعزيــر املدعــى عليــه للحــق العــام‬\n‫مبــا يلــي ‪ /1 :‬ســجنه ملــدة أربعــن يوم ـ ًا يحتســب منهــا مــا أمضــاه مــن‬\n‫توقيــف بســبب هــذه القضيــة ‪ /2‬جلــده خمســون جلــدة مكــررة ثــاث‬\n‫مــرات بــن كل مــرة وأخــرى مــا ال يقــل عــن أســبوع هــذا مــا ظهــر لــي‬\n‫وبــه حكمــت ‪ ،‬وأوصــي بإبعــاد املدعــى عليــه عــن البــاد اتقــاء شــره‬\n‫‪ ،‬وبعــرض احلكــم علــى املدعــي العــام قــرر اعتراضــه ‪ ،‬وطلــب رفعــه‬\n‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة ‪ ،‬وبعرضــه علــى املدعــى‬\n‫عليــه قــرر قناعتــه باحلكــم ‪ ،‬وعليــه قــررت رفــع القــرار مــع كامــل‬\n‫املعاملــة إلــى محكمــة االســتئناف مبكــة املكرمــة لتدقيــق احلكــم‬\n‫كاملتبــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪0000/00/00‬ه ـ‬\n\n\n                                                                                       ‫‪84‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪ :‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n     ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة املســاعد بينبع برقــم ‪ ....‬وتاريخ ‪0000/0/00‬هـ‬\n     ‫املرفــق بهــا القــرار الشــرعي رقــم ‪ ....‬وتاريــخ ‪ 0000/00/00‬ه ـ الصــادر‬\n     ‫مــن فضيلــة الشــيخ ‪ ....‬القاضــي يف احملكمــة العامــة بينبــع‪ ،‬املتضمــن‬\n     ‫دعــوى املدعــى العــام ضــد ‪ ....‬اجلنســية ‪ ....‬املتهــم بقضية حتــرش بالفتيات‬\n                           ‫أمــام مدرســة للبنــات احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n     ‫وبدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم بعــد‬\n     ‫اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                             ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪85‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":79,"source_page_end":85,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"731679452e89848204b11066775d10c809a1d953f016562f3709235607fb4b3e","normalized_text_hash":"8f041af41d0cc3493c2625cc5c22fb404f540d22acf710e999a2bf3bf1a23c82","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p79-33481272"},{"id":"75b16564-b6c3-5108-a2c9-5aef2f1cd23b","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -استدراج حدث بالقوة -عدم حضور البينة وطلب االكتفاء بأوراق املعاملة -عدم االعتداد بالشهادة املكتوبة -تخلف الشاهد قرينة على رجوعه عن الشهادة -عدم إلزام الشاهد باحلضور - جهالة حال الشاهد موجب لرد شهادته -رد دعوى (صرف نظر ) لعدم الثبوت -انتهاء احلق اخلاص بالتنازل .","document_number":"3424400","case_number":"34144313","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/27","year":"1434","subject":"حترش -استدراج حدث بالقوة -عدم حضور البينة وطلب االكتفاء بأوراق املعاملة -عدم االعتداد بالشهادة املكتوبة -تخلف الشاهد قرينة على رجوعه عن الشهادة -عدم إلزام الشاهد باحلضور - جهالة حال الشاهد موجب لرد شهادته -رد دعوى (صرف نظر ) لعدم الثبوت -انتهاء احلق اخلاص بالتنازل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3424400 :‬تاريخه‪1434/1/27 :‬هـ‬\n                   ‫رقم الدعوى‪34144313:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34169022:‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n‫حترش ‪ -‬استدراج حدث بالقوة ‪ -‬عدم حضور البينة وطلب االكتفاء‬\n‫بــأوراق املعاملــة ‪ -‬عــدم االعتــداد بالشــهادة املكتوبــة ‪ -‬تخلــف الشــاهد‬\n‫قرينــة علــى رجوعــه عــن الشــهادة ‪ -‬عــدم إلــزام الشــاهد باحلضــور ‪-‬‬\n‫جهالــة حــال الشــاهد موجــب لــرد شــهادته ‪ -‬رد دعــوى (صــرف نظــر )‬\n                      ‫لعــدم الثبــوت ‪ -‬انتهــاء احلــق اخلــاص بالتنــازل ‪.‬‬\n\n\n\n\n‫‪ ( -1‬وال يجــوز للقاضــي احلكــم برؤيــة خــط الشــاهد احتياطـ ًا للحكــم‬\n                                              ‫) كشــاف القنــاع (‪.)337/4‬‬\n                           ‫‪ -2‬املادة (‪ )120‬من نظام املرافعات الشرعية ‪.‬‬\n                         ‫‪ -3‬املادة (‪ )169‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه مبحاولــة إدخــال‬\n‫حــدث إلــى منزلــه بالقــوة لغــرض ســيء وطلــب إثبــات مــا أســند إليــه‬\n‫وإيقــاع العقوبــة التعزيريــة عليــه حيــث ورد بــاغ للشــرطة عــن تعــرض‬\n‫حــدث يبلــغ مــن العمــر (‪ )14‬عامــا حملاولــة املدعــى عليــه إدخالــه مبنزلــه‬\n‫بالقــوة حتــى حضــر شــخصان وخلصــاه منــه ‪ ،‬أنكــر املدعــى عليــه‬\n‫التهمــة املوجهــة إليــه وقــرر املدعــي العــام طلبــه املهلــة إلحضــار البينــة‬\n\n                                                                                      ‫‪86‬‬\n\f     ‫فأمهــل ثــاث جلســات حتــى قــرر عــدم متكنــه واالكتفــاء مبــا جــاء‬\n     ‫يف طيــات املعاملــة مــن أدلــة وقرائــن ‪ ،‬وإلنــكار املدعــى عليــه دعــوى‬\n     ‫ا ‪ ،‬ونظــر ًا لعجــز املدعــي العــام عــن‬  ‫املدعــي العــام جملــة وتفصي ـ ً‬\n     ‫إحضــار بينتــه واملتمثلــة يف الشــاهدين األحــداث ‪ ،‬وال بينــة لــه ســواهما‬\n     ‫‪ ،‬ونظــر ًا لكــون الشــبهة ال تتوجــه علــى املدعــى عليــه مبــا نســبه لــه‬\n     ‫املدعــي العــام ‪ ،‬وألن الشــهادة ال بــد أن تــؤدى مشــافهة يف مجلــس‬\n     ‫احلكــم ملــا نــص عليــه الفقهــاء ‪ ،‬وألن الشــهود الذيــن اســتند املدعــي‬\n     ‫العــام علــى شــهادتهم أحــداث ‪،‬ف وأهــل العلــم لهــم كالم يطــول يف‬\n     ‫قبــول شــهادة الصبيــان ‪ ،‬بــل إن بعضهــم ال يقبلهــا إال فيمــا كان بينهــم‬\n     ‫قبــل أن يتفرقــوا ‪ ،‬فكيــف إذا كانــت علــى غيرهــم ‪ ،‬وكيــف إذا لــم‬\n     ‫يحضــروا لتأديتهــا يف مجلــس احلكــم الشــرعي ‪ ،‬لذلــك كلــه فقــد‬\n     ‫قــررت احملكمــة صــرف النظــر عــن دعــوى املدعــي العــام وأخلــت ســبيل‬\n     ‫املدعــى عليــه مــن هــذه الدعــوى وبــه حكمــت ‪ ،‬وبعرضــه علــى الطرفــن‬\n     ‫قــرر املدعــى عليــه قناعتــه باحلكــم بينمــا قــرر املدعــي العــام اعتراضــه‬\n     ‫علــى احلكــم بالئحــة فأفهــم بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n     ‫هــذا اليــوم األحــد املوافــق ‪1434/1/18‬هـ ـ الســاعة العاشــرة صباح ـ ًا‬\n     ‫لــدي أنــا (‪ )........‬القاضــي يف احملكمــة اجلزائيــة بتبــوك فتحــت اجللســة‬\n     ‫ـاء علــى املعاملــة الــواردة لــي مــن هيئــة التحقيــق واالدعــاء العــام برقــم‬\n                                                                                     ‫بنـ ً‬\n     ‫‪ 14814‬وتاريــخ ‪1433/10/16‬ه ـ واحملالــة لــي بشــرح فضيلــة الرئيــس‬\n\n‫‪87‬‬\n\f‫رقــم ‪ 33608728‬وتاريــخ ‪1433/10/17‬هـ ـ وفيهــا حضــر املدعــي‬\n‫العــام (‪ )........‬واملعمــد مــن مرجعــه مبوجــب اخلطــاب رقــم (‪ )........‬يف‬\n‫ا يف تقريــر دعــواه بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬    ‫‪1433/9/5‬ه ـ قائ ـ ً‬\n‫االدعــاء لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى (‪ )........‬بنجالديشــي‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )...........‬فقــد ورد يف مركــز‬\n‫شــرطة احلمــراء محضــر دوريــات األمــن رقــم (‪ )...........‬وتاريــخ‬\n‫‪1433/12/29‬ه ـ املتضمــن بــاغ املواطــن (‪ )........‬عــن تعــرض ابــن أختــه‬\n‫احلــدث (‪)14( )........‬عام ـ ًا حملاولــة إدخالــه منــزل املدعــى عليــه بالقــوة‪.‬‬\n‫وبســماع أقــوال احلــدث (‪ )........‬أفــاد بأنــه كان أمــام منــزل املدعــى عليــه‬\n‫وهــو مقابــل منزلهــم وكان ينــزل أغــراض مــن ســيارته وســقطت منــه‬\n‫بطاقــة فأخذهــا احلــدث وأعطاهــا املدعــى عليــه وقــام بخنقــه ووضــع‬\n‫يــده علــى فمــه وســحبه بالقــوة إلــى املنــزل وجــاء شــخصان وهمــا ‪.....‬‬\n‫‪......‬و‪......................‬واســتطاعوا تخليصــه مــن بــن يــدي املدعــى عليــه‪.‬‬\n‫وباســتجواب املدعــى عليــه‪........... /‬أفــاد أنــه يف يــوم الســبت الســاعة‬\n‫الواحــدة والنصــف ظهــر ًا كان معــه اثنــن مــن اجلنســية البنجالدشــية‬\n‫وكان هنــاك خمســة أطفــال يقومــون بأخــذ العفــش الــذي كان يف‬\n‫ســيارته وأخــذوا بطاقــة صديــق لــه وقالــوا أنــت علــي بابــا وقــام بإخبــار‬\n‫والدهــم وقتهــا مباشــرة ‪ -‬ومبواجهــة كل مــن املدعــى عليــه واحلــدث‪/‬‬\n‫‪...........‬أفــاد احلــدث بــأن املدعــى عليــه هــو مــن قــام مبحاولــة إدخالــه‬\n‫املنــزل بالقــوة وأنكــر املدعــى عليــه ذلــك وأصــر كل منهــم علــى أقوالــه‬\n‫وبســماع شــهادة احلــدث‪ )13(........... /‬عام ـ ًا أفــاد بأنــه أثنــاء ذهابــه‬\n‫للســوبر ماركــت شــاهد املدعــى عليــه ‪...........‬ممســكا أخــاه ‪...........‬‬\n‫برقبتــه ويحــاول إدخالــه املنــزل ‪ -‬وبســماع شــهادة احلــدث‪)13(........... /‬‬\n\n\n                                                                                      ‫‪88‬‬\n\f     ‫عام ـ ًا أفــاد بأنــه أثنــاء ذهابــه للبقالــة مــع‪........... ...........‬شــاهد املدعــى‬\n     ‫عليــه ‪...........‬واضعــا يــده علــى فــم ‪...........‬ويحــاول إدخالــه إلــى املنــزل‬\n     ‫بالقــوة وحــاول هــو و‪...........‬تخليصــه مــن يــده ‪ -‬وقــد أســفر التحقيــق‬\n     ‫إلــى توجيــه االتهــام للمدعــى عليــه‪ ........... /‬مبحاولــة إدخــال حــدث إلــى‬\n     ‫منزلــه بالقــوة لغــرض ســيء ‪ -‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جاء‬\n     ‫يف شــهادة األحــداث املدونــة باللفــة رقــم (‪ ، )14-13‬وحيــث أن مــا أقــدم‬\n     ‫عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‪ -1 :‬إثبــات‬\n     ‫مــا أســند إليــه‪ -2.‬احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك رادعــة لــه‬\n     ‫وزاجــرة لغيــره‪ -3.‬إبعــاده عــن البــاد اتقــاء لشــره بعــد نفــاذ محكوميتــه‪.‬‬\n     ‫(علمـ ًا بــان احلــق اخلــاص انتهــى بالتنــازل) هــذه دعــواي وبعــرض ذلــك على‬\n     ‫ا ‪ - :‬بواســطة املترجــم ‪...........‬بنغالــي اجلنســية‬    ‫املدعــى عليــه أجــاب قائـ ً‬\n     ‫مبوجــب رخصــة اإلقامــة رقــم (‪ - )...........‬مــا ذكــره املدعــي العــام مــن‬\n     ‫اتهامــي مبحاولــة إدخــال حــدث إلــى منزلــي بالقــوة لغــرض ســيء فهــذا‬\n     ‫غيــر صحيــح هــذه إجابتــي وبعــرض ذلــك علــى املدعــي العام أجــاب بقوله‬\n     ‫مــا ذكرتــه هــو الصحيــح ولــدي بينــة علــى ذلــك أطلــب إمهالــي ألجــل‬\n     ‫إحضارهــا لــذا فقــد جــرى رفــع اجللســة حلــن إحضــار املدعي العــام لبينته‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/1/21‬ه ـ‬\n     ‫الســاعة العاشــرة والنصــف صباحـ ًا فتحــت اجللســة وفيهــا حضــر املدعــي‬\n     ‫العــام واملدعــى عليــه واملترجــم ‪ -...........‬وبســؤال املدعــي العــام عــن بينتــه‬\n     ‫التــي وعــد بإحضارهــا أجــاب بقولــه لــم أســتطع إحضــار الشــهود وأطلــب‬\n     ‫مهلــة ألجــل إحضارهــم مــرة أخــرى هكــذا قــرر املدعــي العــام وحيــث‬\n     ‫األمــر كذلــك فقــد قــررت رفــع اجللســة وحــددت موعــد ًا جديــد ًا لســماع‬\n     ‫البينــة وذلــك يف يــوم الثالثــاء القــادم املوافــق ‪1434/1/27‬ه ـ الســاعة‬\n\n\n‫‪89‬‬\n\f‫العاشــرة صباحـ ًا وأفهمــت املدعــي العــام أنــه ســيعد عاجــز ًا عــن إحضــار‬\n‫بينتــه يف حــال لــم يحضرهــا يف املوعــد القــادم فتفهــم ذلــك وعليــه جــرى‬\n‫التوقيــع وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫حــرر يف الســاعة العاشــرة والنصــف مــن ضحــى يــوم األربعــاء املوافــق‬\n‫‪1434/1/21‬ه ـ ثــم يف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n‫عليــه واملترجــم ‪ -...........‬وبســؤال املدعــي العــام عــن بينتــه التــي وعــد‬\n‫بإحضارهــا أجــاب بقولــه لــم أســتطع إحضــار الشــهود وأقــرر االكتفــاء‬\n‫مبــا جــاء يف طيــات املعاملــة مــن أدلــة وقرائــن هكــذا قــرر املدعــي العــام‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ‪ -‬وإلنــكار املدعــى عليــه‬  ‫‪ -‬فبنـ ً‬\n‫ا ‪ -‬ونظــر ًا لعجــز املدعــى العــام عــن‬\n                                         ‫دعــوى املدعــي العــام جملــة وتفصيـ ً‬\n‫إحضــار بينتــه واملتمثلــة يف الشــاهدين األحــداث ‪ -‬وال بينــه ســواها ‪-‬‬\n‫ونظــر ًا لكــون الشــبهة ال تتوجــه علــى املدعــى عليــه مبــا نســبه لــه املدعي‬\n‫العــام وألن الشــهادة ال بــد أن تــؤدى مشــافهة يف مجلــس احلكــم ملــا نــص‬\n‫عليــه الفقهــاء ومــن ذلــك قولهــم ( وال يجــوز للقاضــي احلكــم برؤيــة خــط‬\n‫الشــاهد احتياطـ ًا للحكــم ) انظــر كشــاف القنــاع (‪ )337/4‬وقــد نــص‬\n‫نظــام املرافعــات الشــرعية مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف‬\n‫أداء الشــهادة مبذكــرات مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا كمــا‬\n‫نــص نظــام اإلجــراءات اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف‬\n‫مجلــس القضــاء كمــا يف املــادة (‪ )169‬ونظــر ًا ألن تخلــف الشــاهد عــن‬\n‫ا علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف‬     ‫احلضــور يعتبــر دليـ ً‬\n‫حقــوق اهلل تعالــى ال يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر‬\n‫مجهــول احلــال ‪ -‬وألن الشــهود الذيــن اســتند املدعــي العام على شــهادتهم‬\n‫أحــداث ‪ -‬وأهــل العلــم لهــم كالم يطــول يف قبــول شــهادة الصبيــان ‪ -‬بــل‬\n\n\n                                                                                       ‫‪90‬‬\n\f     ‫إن بعضهــم ال يقبلهــا إال فيمــا كان بينهــم قبــل أن يتفرقــوا ‪ -‬فكيــف‬\n     ‫إذا كانــت علــى غيرهــم ‪ -‬وكيــف إذا لــم يحضــروا لتأديتهــا يف مجلــس‬\n     ‫احلكــم الشــرعي ! ‪ -‬لذلــك كلــه فقــد قــررت صــرف النظــر عــن دعــوى‬\n     ‫املدعــى العــام وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى هــذا مــا‬\n     ‫ظهــر لــي وبــه حكمــت ‪ -‬وبعرضــه علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫قناعتــه باحلكــم وقــرر املدعــي العــام اعتراضــه علــى احلكــم بالئحــة‬\n     ‫فأجبتــه إلــى طلبــه وأفهمتــه بتعليمــات االســتئناف حيــال ذلــك ثــم جــرى‬\n     ‫تســليمه نســخة مــن القــرار ليبــدأ ميعــاد االعتــراض مــن تاريــخ احلكــم‬\n     ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n     ‫وصحبــه وســلم ‪ -‬حــرر يف الســاعة العاشــرة وخمســن دقيقــة مــن ضحــى‬\n                                              ‫يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولى‬\n     ‫لتدقيــق القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم‬\n     ‫‪ 3467825‬وتاريــخ ‪1434/2/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة الشــيخ (‪ )........‬برقــم ‪ 3424400‬وتاريــخ ‪1434/1/27‬ه ـ اخلاصــة‬\n     ‫بدعــوى املدعــي العــام ضــد (‪ )........‬يف قضيــة اســتدراج حــدث علــى‬\n     ‫النحــو املوضــح يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أنــه يوجــد تكــرار يف‬\n     ‫دعــوى املدعــي العــام يف الصفحــة األولــى مــن القــرار والضبــط لتــايف‬\n     ‫ذلــك‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪91‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":86,"source_page_end":91,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b6f679badc70d5a1ad6418b5ec79e9372d210b6b11eecda120397a61692dde6e","normalized_text_hash":"9fcbe1f1e47e6ae707663a6ff2526f02b4985c9ce8d7755ec1a4a5ccd77e5bae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p86-3424400"},{"id":"da9989ee-baf7-512b-9bd5-8de54849a54c","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -حترش بالنساء عن طريق اجلوال -مساعدة شخص ألمر محرم -تستر -إقرار حتقيق ا -التعزير بالسجن واجللد -توصية","document_number":"344926","case_number":"33444620","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملالحظة أن احلكم قليل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/06","year":"1434","subject":"حترش -حترش بالنساء عن طريق اجلوال -مساعدة شخص ألمر محرم -تستر -إقرار حتقيق ا -التعزير بالسجن واجللد -توصية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 344926 :‬تاريخه‪1434/01/06 :‬هـ‬\n                   ‫رقم الدعوى‪33444620:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 3418859:‬تاريخه‪1434/01/21:‬هـ‬\n\n\n‫حتــرش ‪ -‬حتــرش بالنســاء عــن طريــق اجلــوال ‪ -‬مســاعدة شــخص ألمــر‬\n‫محــرم ‪ -‬تســتر ‪ -‬إقــرار حتقيقـ ًا ‪ -‬التعزيــر بالســجن واجللــد ‪ -‬توصيــة‬\n                                                                 ‫باإلبعــاد ‪.‬‬\n\n\n\n\n‫قولــه تعالــى‪( :‬إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا‬\n                                                    ‫لهــم عــذاب أليــم) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد وافديــن اثنــن يعمــان يف محــل مفروشــات‬\n‫باتهــام األول منهمــا بالتحــرش بفتاتــن عنــد دخولهمــا احملــل وقيــام‬\n‫الثانــي مبســاعدة األول والوقــوف علــى بــاب احملــل للمراقبــة ‪ ،‬والتســتر‬\n‫علــى األول وطلــب املدعــي العــام إثبــات مــا اســند لهمــا واحلكــم عليهمــا‬\n‫بعقوبــة تعزيريــة رادعــة‪ ،‬مت القبــض علــى املدعــي عليهمــا مــن قبــل‬\n‫الدوريــات األمنيــة بنــاء علــى شــكوى مــن شــقيق احــد الفتاتــن وبنــاء‬\n‫علــى أقــوال الفتــاة أن املدعــي عليــه األول قــام بالتحــرش بهــا أثنــاء‬\n‫دخولهــا احملــل الــذي يعمــل بــه املدعــي عليهمــا وان املــرأة األخــرى عندمــا‬\n‫دخلــت احملــل حتــرش بهــا املدعــي عليــه األول جنســي ًا وكان املتهــم‬\n‫الثانــي يقــوم باملراقبــة‪ ،‬أجــاب املدعــي عليهمــا علــى الدعــوى باإلنكار‪،‬‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫يف جلســة أخــرى حضــر املدعــى عليــه األول ولــم يحضــر الثانــي‪ ،‬وجــود‬\n     ‫إقــرار للمدعــى عليــه األول حتقيق ـ ًا بالتحــرش باملبلغــة‪ ،‬ثبــت إدانــة‬\n     ‫املدعــى عليــه األول وصــدر احلكــم بتعزيــره بالســجن واجللــد والتوصيــة‬\n     ‫باإلبعــاد‪ ،‬وعلــى اجلهــة املختصــة إحضــار الثانــي حملاكمته‪،‬صــدر قــرار‬\n     ‫محكمــة االســتئناف باملالحظــة أن احلكــم قليــل‪ ،‬مت زيــادة تعزيــر‬\n                    ‫املدعــى عليــه‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33443759‬‬\n     ‫وتاريــخ ‪1433/07/05‬ه ـ املقيــدة باحملكمة برقــم ‪ 331245482‬وتاريخ‬\n     ‫‪ 1433/07/02‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/07/07‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 09 : 15‬وفيهــا قــدم املدعــي العــام (‪ )........‬دعــواه‬\n     ‫ضــد ‪ )35 ( )........(-1‬عامـاً‪ -‬بنجالديشــي اجلنســية ‪ ،‬مبوجــب البطاقــة‬\n     ‫البديلــة رقــم (‪ ،)...........‬موقــوف بســجون محافظــة جــدة مبوجــب أمــر‬\n     ‫متديــد التوقيــف رقــم ‪ ............‬ه ـ م‪33444/3/2‬وتاريــخ ‪1433 /5/17‬ه ـ‬\n                       ‫‪ .‬اســتناد ًا للمــادة (‪)108‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n     ‫‪35 ،...........-2‬عام ـ ًا بنجالديشــي اجلنســية مبوجــب رخصــه إقامــة رقــم‬\n     ‫(‪ )...........‬مطلــق الســراح بكفالــة حضوريــه اســتناد للمــادة(‪ )120‬مــن‬\n                                                       ‫نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n     ‫حيــث أنــه بتاريــخ ‪1433/5/11‬ه ـ مت القبــض علــى املتهمــن املذكوريــن‬\n                                                         ‫مــن قبــل الدوريــات األمنيــة‬\n\n‫‪93‬‬\n\f‫بنــاء علــى شــكوى ‪)22( ...........‬عامــا ســعودي اجلنســية بــأن املتهــم‬\n‫األول قــام بالتحــرش بشــقيقته الفتــاة ‪...........‬وذلــك أثنــاء دخولهــا حملــل‬\n‫املفروشــات التــي يعمــل بهــا املتهمــان وكذلــك جــاء يف أقــوال الفتــاة بــأن‬\n‫املتهــم األول قــام بالتحــرش بهــا أثنــاء دخولهــا لشــراء موكيــت مــن احملــل‬\n‫الــذي يعمــل بــه املتهمــان وأنــه قــام بوضــع يــده علــى صدرهــا وطلــب منهــا‬\n‫أن تقــوم مبســك ذكــره وكذلــك عنــد حضــور زوجــة أخيهــا املــرأة‬\n‫‪.........../‬للمحــل الــذي يعمــل بــه املتهمــان قــام املتهــم األول بالتحــرش بهــا‬\n‫جنســي ًا وعمــل حــركات غيــر الئقــة وكان املتهــم الثانــي يقــف علــى‬\n‫بــاب احملــل ويقــوم باملراقبــة‪ .‬وقــد حضــر أخــوة الفتــاة وقامــوا بضــرب‬\n‫املتهمــن حســب مــا ورد يف أقــوال املتهمــن وقــد مت فــرز أوراق مســتقلة‬\n                                    ‫لدعــوى الضــرب وأحيلــت ملركــز الشــرطة ‪.‬‬\n‫وباســتجواب املتهــم األول‪ ،‬أفــاد بأنــه حضــرت إليــه الفتــاه‪........... /‬‬\n‫لشــراء موكيــت وأعطاهــا كــرت احملــل ورقــم جوالــه ثــم خرجــت مــن‬\n‫احملــل وبعدهــا قامــت باالتصــال بــه وكلمتــه وقالــت لــه يــا حبيبــي ثــم‬\n‫قــال لهــا أنــت حبيبتــي وقــال تعالــي إلــى احملــل وإن شــاء اهلل أراعيــك ‪.‬‬\n‫‪-2‬وباســتجواب املتهــم الثانــي أفــاد بــأن الفتــاة حضــرت إلــى احملــل الــذي‬\n‫يعمــل بــه هــو واملتهــم األول ودخلــت ولــم يكــن معهــا أحــد ودخلــت يف‬\n‫اجلــزء األخــر مــن احملــل وكان يقــف علــى بــاب احملــل وهــي عنــد املتهــم‬\n‫األول لشــراء موكيــت وقــد مكثــت الفتــاة عنــده حوالــي ثلــث ســاعة ‪.‬‬\n‫وبســماع أقــوال الفتــاة ‪...........‬أفــادت بأنهــا أثنــاء دخولهــا باحملــل الــذي‬\n‫يعمــل بــه املتهمــن قــام املتهــم األول بالتحــرش اجلنســي بهــا ووضــع يــده‬\n                   ‫علــى صدرهــا وطلــب منهــا رقــم جوالهــا وأنــه اتصــل بهــا ‪.‬‬\n‫وبســماع أقــوال املــرأة ‪...........‬أفــادت أنهــا عندمــا أبلغتهــا الفتــاة ‪...........‬‬\n\n\n                                                                                             ‫‪94‬‬\n\f     ‫بــأن املتهمــن قامــا بالتحــرش بهــا ذهبــت رفــق أهلهــا حملــل املتهمــن وعند‬\n     ‫دخولهــا للمحــل قــام املتهــم األول بالتحــرش بهــا وقــد أســفر التحقيــق مــع‬\n     ‫املتهمــن إلــى توجيــه االتهــام لــأول بالتحــرش بالفتــاة ‪ ...........‬وباملــرأة‬\n     ‫‪ ...........‬عنــد دخولهمــا باحملــل الــذي يعمــل بــه وللثانــي مبســاعدة األول‬\n     ‫والوقــوف علــى بــاب احملــل للمراقبــة والتســتر علــى األول وذلــك لألدلــة‬\n                                                                                  ‫والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬مــا جــاء يف أق ـ ــوال املتهمــن املدونــة بامل ـح ـ ـ ـ ـ ـ ــضر املرف ـ ـ ــق لفــه رقــم‬\n                                                                                   ‫( ‪. ) 17-16-13‬‬\n     ‫‪ -2‬مــا جــاء يف أقــوال الفتــاة واملــرأة املدونــة بال ــمحضر املرفــق لفــه رقــم‬\n                                                                                         ‫( ‪. ) 17-16‬‬\n            ‫وبالبحث عن سوابقهما لم يعثر لهما على سوابق مسجلة عليهما ‪.‬‬\n     ‫وحيــث أن مــا أقــدم عليــه املذكــوران فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫لــذا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة‬\n     ‫رادعــه‪ ( .‬علمـ ًا بــأن احلــق اخلــاص مــازال قائمـ ًا ) ثــم حضــر املدعــي العــام‬\n     ‫واملدعــى عليــه األول ‪...........‬أمــا املدعــى عليــه الثانــي فســيتم محاكمتــه‬\n     ‫حــن حضــوره وبســؤاله بواســطة مترجــم احملكمــة ‪...........‬باكســتاني‬\n     ‫ا مــا ذكــره املدعــي العــام يف دعــواه‬              ‫اجلنســية إقامــة رقــم ‪...........‬قائ ـ ً‬\n     ‫غيــر صحيــح والصحيــح أن املدعيــة حضــرت للمحــل بصحبــة امــرأة يف‬\n     ‫املــرة األولــى وبقيــت إحداهــن عنــد بــاب احملــل واألخــرى داخلــه وقمــت‬\n     ‫بعــرض بضاعــة احملــل عليهــا ثــم خرجــت بعــد إعطائــي لهــا رقــم جوالــي‬\n     ‫اخلــاص وبعدهــا قامــت باالتصــال علــي وقلــت لهــا تعالــي يــا حبيبتــي‬\n     ‫للمحــل وأراعيــك يف املــرة القادمــة ثــم حضــر إخوانهــا وقامــوا بضربــي‬\n     ‫وضــرب ‪...........‬وغيــر صحيــح انــي وضعــت يــدي علــى صدرهــا أو‬\n\n\n‫‪95‬‬\n\f‫حترشــت بهــا جســدي ًا هكــذا أجــاب فجــرى منــي ســؤاله كيــف تقــول‬\n‫ا أنــا معتــاد علــى قــول‬‫المــرأة ال تعرفهــا باجلــوال يــا حبيبتــي فأجــاب قائـ ً‬\n‫هــذه الكلمــة وهــي علــى لســاني مــع اجلميــع وبســؤال املدعــي العــام عــن‬\n‫بينتــه قــال أطلــب إمهالــي إلحضارهــا يف اجللســة القادمــة لــذا قــررت رفــع‬\n‫اجللســة إلــى أن يحضــر املدعــي العــام بينتــه وصلــى اهلل وســلم علــى نبينــا‬\n                                                                            ‫محمــد ‪.‬‬\n‫ثــم يف يــوم الســبت املوافــق‪ 1433/07/12‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة وفيهــا حضــر املدعــي العــام واملدعــى عليــه الثانــي ‪...........‬‬\n‫وبســؤاله عمــا نســب إليــه بدعــوى املدعــي العــام اجــاب قائــا وهــو‬\n‫يتحــدث اللغــة العربيــة بطالقــة ان مــا ذكــره املدعــي العــام يف دعواه غير‬\n‫صحيــح والصحيــح اننــي اعمــل يف احملل املجاور حملل املدعى عليه االول‬\n‫‪...........‬يف ســوق الصواريــخ وبعــد احلــادث بيــوم طلــب منــي مديــر ‪...........‬‬\n‫وهــو باكســتاني اجلنســية ان اقــوم مبســاعدته يف ترتيــب املوكيــت‬\n‫املعــروض أمــام محلهــم واثنــاء عملــي تفاجــأت بحضــور أشــخاص ال‬\n‫اعرفهــم يبلــغ عددهــم خمســة اشــخاص قامــوا بضربــي بــدون ســبب ثــم‬\n‫هربــت وغيــر صحيــح أننــي قمــت مبراقبــة احملــل ل‪ ...........‬حتــى يتمكــن‬\n‫مــن فعــل مــا يريــد وال اعلــم ان كان حتــرش باملــرأة هكــذا اجــاب لــذا‬\n‫قــررت رفــع اجللســة حلــن ورود بينــة املدعــي العــام حيــث ان املدعــى عليــه‬\n‫األول ‪...........‬انكــر الدعــوى ايضــا كمــا يف اجللســة الســابقة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n‫يف ‪ 1433/07/12‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي‬\n‫باحملكمــة اجلزئيــة مبحافظــة جــدة القائــم بعمــل فضيلــة الشــيخ ‪...........‬‬\n‫مبوجــب خطــاب التكليــف رقــم ‪ 332186290‬يف ‪1433/12/19‬ه ـ‬\n\n\n                                                                                         ‫‪96‬‬\n\f     ‫ففــي يــوم األحــد املوافــق ‪1434/01/11‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫العاشــرة وفيهــا حضــر املدعــي العــام واملدعــى عليــه األول ‪...........‬ولــم‬\n     ‫يحضــر املدعــى عليــه الثانــي وال وكيــا ً شــرعي ًا عنــه وقــرر املدعــي‬\n     ‫العــام بأنــه ال يوجــد لديــه بينــة ســوى مــا هــو موجــود بــأوراق املعاملــة هــذا‬\n     ‫وحيــث جــرى االطــاع علــى أوراق املعاملــة فوجــدت إقــرار املدعــى عليــه‬\n     ‫بقولــه للمدعيــة يــا حبيبتــي يف اجلــوال عندمــا كلمتــه ولــم أجــد مــا يؤيــد‬\n     ‫ـاء علــى جميــع مــا تقــدم ولقولــه‬‫باقــي مــا ورد يف دعــوى املدعــي العــام فبنـ ً‬\n     ‫تعالــى (إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن آمنــوا أولئــك لهــم‬\n     ‫عــذاب أليــم) وملــا يف قــول املدعــى عليــه مــن عصيان هلل ورســوله وانتهاك‬\n     ‫لألعــراض فقــد ثبــت لــدي إدانــة املدعــى عليــه بالتحــرش بالفتــاة ‪...........‬‬\n     ‫عــن طريــق اجلــوال ولــم يثبــت لــدي باقــي مــا أســند إليــه وحكمــت‬\n     ‫عليــه لقــاء ذلــك بســجنه ملــدة شــهرين يحتســب منهــا مــدة إيقافــه علــى‬\n     ‫ذمــة هــذه القضيــة وإبعــاده عــن البــاد بعــد انتهــاء تنفيــذ محكوميتــه‬\n     ‫وعــدم الســماح لــه بالعــودة إليهــا مــرة اخــرى وبعرضــه علــى الطرفــن‬\n     ‫قــرر املدعــى عليــه القناعــة وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n     ‫واســتعد بتقــدمي الئحــه اعتراضيــة وعلــى اجلهــة املختصــة إحضــار املدعــى‬\n     ‫عليــه الثانــي حملاكمتــه وبــه ختمــت اجللســة الســاعة العاشــرة والربــع‬\n                   ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/1/11‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/06/03‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام واملدعــى‬\n     ‫عليــه وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف وبرفقهــا‬\n     ‫القــرار الصــادر مــن الدائــرة اجلزائيــة الســابعة برقــم ‪34193113‬‬\n     ‫وتاريــخ ‪1434/4/21‬ه ـ واملتضمــن أنــه بدراســة القــرار وصــورة ضبطــه‬\n\n\n‫‪97‬‬\n\f‫والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن‬\n‫اجلــزاء احملكــوم بــه قليــل وال يتناســب مــع اجلــرم الســيما أن القاضــي‬\n‫اســتدل باآليــة الكرميــة وهــي قويــة يف االســتدالل واجلــزاء قليــل والبــد‬\n‫مــن إضافــة الســجن أيض ـ ًا واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم قاضــي اســتئناف ‪ ...........‬قاضــي‬\n‫اســتئناف ‪...........‬قاضــي اســتئناف رئيــس الدائــرة ‪ ...........‬وعليــه أجيــب‬\n‫أصحــاب الفضيلــة وفقهــم اهلل بأنــه ولوجاهــة مــا ذكــروه فقــد رجعــت‬\n‫عــن حكمــي الســابق وحكمــت بســجنه ثالثــة أشــهر وجلــده خمســن‬\n‫ســوط ًا وبعــرض ذلــك علــى املدعــى عليــه قــرر القناعــة واملدعــي العــام ال‬\n‫زال علــى اعتراضــه ومكتفي ـ ًا مبــا قدمــه مــن الئحتــه االعتراضيــة وبــه‬\n‫ختمــت اجللســة الســاعة العاشــرة والربــع وصلــى اهلل وســلم علــى نبينــا‬\n                                             ‫محمــد حــرر يف ‪1434/6/03‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة رقــم ‪ 331245482‬وتاريــخ‬\n‫‪1434/7/10‬هـ ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪...........‬‬\n‫القائــم بعمــل الشــيخ ‪...........‬القاضــي باحملكمــة اجلزائيــة مبحافظــة‬\n‫جــدة رقــم ‪ 3413257‬وتاريــخ ‪1434/1/17‬ه ـ احملكــوم فيــه مبــا دون‬\n‫بباطــن القــرار املتضمــن دعــوى املدعــى العــام ضــد‪........... /‬ورفيقــه‬\n‫املتهمــن يف التحــرش بفتــاه وبدراســة القــرار وصــورة ضبطــه والئحتــه‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل‬\n      ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                    ‫‪98‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":92,"source_page_end":98,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a6d26486bc6b90266acb4cab5c82b68fce2a665e81d3ac29d82902b010b61d47","normalized_text_hash":"f7af84cb608b32793f9a0d13a5ccb1de3e6135f7b93e70c7927028024aaa089c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p92-344926"},{"id":"2e80f71e-f2ba-55b3-b8ec-20cc1b04d650","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -حترش جنسي بامرأة -الرجوع عن اإلقرار يف احلق العام مورث للشبهة املوجبة للتعزير -رد طلب املدعي العام ثبوت اإلدانة وإثبات توجه التهمة -التعزير بالسجن واجللد لتوجه التهمة .","document_number":"34188141","case_number":"34121146","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/25","year":"1434","subject":"حترش -حترش جنسي بامرأة -الرجوع عن اإلقرار يف احلق العام مورث للشبهة املوجبة للتعزير -رد طلب املدعي العام ثبوت اإلدانة وإثبات توجه التهمة -التعزير بالسجن واجللد لتوجه التهمة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34188141 :‬تاريخه‪1434/04/25 :‬هـ‬\n                          ‫رقم الدعوى‪34121146:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34241018‬تاريخه‪1434/06/14:‬هـ‬\n\n\n      ‫حتــرش ‪ -‬حتــرش جنســي بامــرأة ‪ -‬الرجــوع عــن اإلقــرار يف احلــق العــام‬\n      ‫مــورث للشــبهة املوجبــة للتعزيــر ‪ -‬رد طلــب املدعــي العــام ثبــوت اإلدانــة‬\n           ‫وإثبــات توجــه التهمــة‪ -‬التعزيــر بالســجن واجللــد لتوجــه التهمــة ‪.‬‬\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف‬\n                                                             ‫تســبيب حكمــه‪.‬‬\n\n\n\n      ‫جــرى توجيــه االتهــام للمدعــى عليــه بالتحــرش اجلنســي بامــرأة وطلــب‬\n      ‫املدعــي العــام إيقــاع العقوبــة التعزيريــة املناســبة علمــا بــأن احلــق اخلــاص‬\n      ‫انتهــى بالتنــازل ‪ ،‬حيــث تقدمــت امــرأة بشــكوى ضــده بأنــه طلــب‬\n      ‫منهــا ملــس يدهــا وكشــف غطــاء وجههــا فهربــت وأقــر لــدى جهــات‬\n      ‫التحقيــق بأنــه طلــب منهــا الســام ومــد يــده لهــا فرفضــت ثــم طلــب‬\n      ‫منهــا كشــف وجههــا ليعــرف أهــي بنــت جيرانــه أم ال ‪ ،‬وباســتجوابه‬\n      ‫أثنــاء احملاكمــة أنكــر الدعــوى جملــة وتفصيــا ‪ ،‬بطلــب البينــة مــن‬\n      ‫املدعــي العــام قــرر بــأن بينتــه اعترافــه املــدون املرفــق باملعاملــة ‪ ،‬بعــرض‬\n      ‫اإلقــرار علــى املدعــى عليــه دفــع بــأن اإلقــرار نــزع منــه إكراهــا ‪ ،‬جــرى‬\n      ‫ســؤال املدعــى عليــه هــل لديــه بينــة علــى دفعــه فأجــاب بالنفــي ‪ ،‬بنــاء‬\n      ‫علــى دعــوى املدعــي العــام ولعــدم قيــام الدليــل القاطــع علــى مــا اتهــم بــه‬\n‫‪99‬‬\n\f‫املدعــى عليــه إال اعترافــه حتقيقــا الــذي رجــع عنــه ويوجــه لــه التهمــة‬\n‫ولعــدم وجــود ســوابق فقــد قــررت احملكمــة رد دعــوى املدعــي العــام‬\n‫طلبــه إثبــات اإلدانــة وحكمــت عليــه لتوجــه التهمــة بالســجن شــهرا مــن‬\n‫تاريــخ إيقافــه وجلــده خمســن جلــدة دفعــة واحــدة ‪ -‬جرى عــرض احلكم‬\n‫علــى الطرفــن فقــرر املدعــى عليــه القناعــة باحلكــم بينمــا قــرر املدعــي‬\n‫العــام االعتــراض بالئحــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫ـاء‬\n ‫أنــا (‪ )........‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة وبنـ ً‬\n‫علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس برقــم ‪34121146‬‬\n‫وتاريــخ ‪1434/3/14‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‪ 34638619‬يف‬\n‫‪1434/3/14‬ه ـ افتتحــت اجللســة يف هــذا اليــوم الســبت ‪1434/3/14‬ه ـ‬\n‫وفيهــا حضــر املدعــي العــام (‪ )........‬وادعــى علــى احلاضــر معــه (‪)........‬‬\n‫بنغالــي اجلنســية باإلقامــة رقــم (‪ )...........‬فبتاريــخ ‪1433/5/13‬ه ـ‬\n‫تقدمــت املجنــي عليهــا (‪ )........‬مصريــة اجلنســية بشــكوى مبركــز‬\n‫شــرطة (‪ )........‬مفادهــا أنهــا عنــد ذهابهــا حملــل الدواجــن الــذي يعمــل بــه‬\n‫املدعــى عليــه لشــراء بيــض قابلهــا املدعــى عليــه وطلــب منهــا أن يلمــس‬\n‫يدهــا وأن تكشــف غطــاء وجههــا فهربــت مــن احملــل وبالتحقيــق مــع‬\n‫املدعــى عليــه اعتــرف مبــا أســند إليــه وأفــاد بــأن املجنــي عليهــا حضــرت‬\n‫للمحــل الــذي يعمــل فيــه لشــراء بيــض وطلــب منهــا الســام ومــد يــده لهــا‬\n‫فرفضــت وذكــر بأنــه طلــب منهــا أن تكشــف غطــاء وجههــا ليعــرف‬\n‫هــل هــي بنــت جيرانــه أم ال وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه‬\n\n                                                                                       ‫‪100‬‬\n\f      ‫مبــا أســند إليــه لألدلــة والقرائــن املوضحــة بالدعــوى لــذا فإننــي أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا بــدر منــه‬\n      ‫علمـ ًا بــأن احلــق اخلــاص منتــه هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليــه أنكرهــا جملــة وتفصيــا وقــال طردتهــا مــن احملــل‬\n      ‫فقــط وال ســوابق لــدي هكــذا قــرر وبعــرض ذلــك علــى املدعــي العــام‬\n      ‫قــال الصحيــح مــا ذكرتــه يف دعــواي وبينتــي اعترافــه املــدون ص (‪)3-2‬‬\n      ‫مــن ملــف التحقيــق وتطابــق أقــوال املدعــى عليه مبــا ورد يف أقوال املجني‬\n      ‫عليهــا وبالرجــوع إلــى ذلــك وجــدت اعترافــا مــن املدعــى عليــه بأنــه مــد‬\n      ‫يــده للمجنــي عليهــا وطلــب منهــا كشــف غطاءهــا وبعرضــه عليــه قــال‬\n      ‫وقعــت عليــه حتــت إكــراه وضغــط فســألته البينــة علــى اإلكــراه فقــال‬\n      ‫ال بينــة لــدي واكتفــى املدعــي العــام مبــا ذكــر فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة ولعــدم قيــام الدليــل القاطــع علــى املدعــى عليــه مبــا‬\n      ‫نســب إليــه ســوى اعترافــه حتقيقــا وقــد رجــع عنــه ويوجــه التهمــة نحــوه‬\n      ‫بفعلتــه ولعــدم وجــود ســوابق عليــه لــذا كلــه فقــد رددت دعــوى املدعــي‬\n      ‫العــام لعــدم ثبــوت إدانــة املدعــى عليــه مبــا نســب إليــه وحكمــت عليــه‬\n      ‫لقــاء توجــه التهمــة نحــوه بالســجن مــدة شــهر مــن تاريــخ إيقافــه وجلــده‬\n      ‫خمســن جلــدة دفعــة واحــدة وبعرضــه عليــه قنــع بــه وقــرر املدعــي العــام‬\n      ‫االعتــراض بالئحــة فأجيــب إلــى طلبــه وبــاهلل تعالــى التوفيــق حــرريف‬\n      ‫‪1434/3/14‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n                                                                            ‫بعــده وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n      ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع على‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة‬\n\n\n‫‪101‬‬\n\f‫برقــم (‪ )34638619‬وتاريــخ (‪1434/6/7‬هــ) املرفــق بهــا القــرار الصادر‬\n‫مــن فضيلــة الشــيخ‪ ،........... /‬القاضــي باحملكمــة اجلزائيــة مبكــة‬\n‫املكرمــة برقــم (‪ )34188141‬وتاريــخ (‪1434/4/15‬هــ) املتضمــن‬\n‫دعــوى املدعــي العــام ضــد‪........... /‬بنغالــي اجلنســية املتهــم يف معاكســة‬\n‫امــرأة ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم لقناعــة‬\n‫املدعــى عليــه‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                              ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪102‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":99,"source_page_end":102,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"35ab46395c7d47c91e5084831e1e91b9915c4e3461bc0f6efb30005482031a69","normalized_text_hash":"e35f84dadb5a3733a8a21d182a96735aa9fd3bea18bd337711ce0339abe8fbca","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p99-34188141"},{"id":"0c6e822e-8288-5550-9f62-34c2aa2f2458","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -إزعاج بإرسال رسائل -إقرار -التعزير بالسجن واجللد -مصادرة جهاز اجلوال -إلغاء الشريحة .","document_number":"34303460","case_number":"34121828","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/23","year":"1434","subject":"حترش -مضايقة امرأة -إزعاج بإرسال رسائل -إقرار -التعزير بالسجن واجللد -مصادرة جهاز اجلوال -إلغاء الشريحة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34303460 :‬تاريخه ‪1434/08/23 :‬هـ‬\n                          ‫رقم الدعوى‪34121828 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34334489:‬تاريخه‪101434/19:‬هـ‬\n\n\n       ‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬إزعــاج بإرســال رســائل ‪ -‬إقــرار ‪ -‬التعزيــر‬\n             ‫بالســجن واجللــد ‪ -‬مصــادرة جهــاز اجلــوال ‪ -‬إلغــاء الشــريحة ‪.‬‬\n\n\n\n\n       ‫‪ -1‬قـ ــوله ص ــلى اهلل عليــه وســلم (لـ ــعن اهلل م ــن خ ـبـ ــب امـ ــرأة علــى‬\n                                                                              ‫زوجـ ــها ) ‪.‬‬\n                                                   ‫‪ -2‬قاعدة ( اإلقرار حجة شرعية ) ‪.‬‬\n                                          ‫‪ -3‬قاعدة (الوسائل لها أحكام املقاصد ) ‪.‬‬\n                            ‫‪ -4‬ما ذكره أهل العلم من مشروعية التعزير باملال ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه مبعاكســة امــرأة و إزعاجهــا‬\n       ‫بالرســائل ‪ ،‬حيــث تقــدم أحــد املواطنــن بشــكوى مفادهــا قيــام املدعــى‬\n       ‫عليــه مبعاكســة وإزعــاج زوجتــه ‪ ،‬عــن طريــق الرســائل القصيــرة ‪،‬‬\n       ‫وقــد أثبــت محضــر تفريــغ الرســائل املرســلة علــى جــوال املــرأة ورود عــدة‬\n       ‫رســائل مــن جــوال املدعــى عليــه‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى‬\n       ‫عليــه لقــاء مــا نســب إليــه ‪ ،‬أقــر املدعــى عليــه مبــا جــاء بدعــوى املدعــي‬\n       ‫ـاء علــى مــا تقــدم ‪ .‬حكمــت احملكمــة بتعزيــر املدعــى عليــه‬       ‫العــام بنـ ً‬\n       ‫بالســجن و اجللــد لقــاء إدانتــه مبــا جــاء بدعــوى املدعــي العــام ومبصــادرة‬\n\n‫‪103‬‬\n\f‫جهــازه اجلــوال و بيعــه و إيــداع قيمتــه يف اخلزينــة العامــة للدولــة و صرفــه‬\n‫للمصالــح العامــة وإلغــاء رقــم الشــريحة ‪ ،‬قنــع املدعــى عليــه باحلكــم‬\n‫وصــدق‬\n     ‫‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة ُ‬\n                                        ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬رئيــس احملكمــة اجلزائيــة‬\n‫باألحســاء املكلــف مبوجــب القــرار مــن معالــي رئيــس مجلــس القضــاء‬\n‫برقــم تاريــخ ‪1434/04/15‬ه ـ والقائــم بأعمــال املكتــب القضائــي‬\n‫الســابع عليــه فبنــاء علــى املعاملــة الــواردة مــن هيئــة التحقيــق واالدعــاء‬\n‫العــام باألحســاء برقــم تاريــخ ‪1434/03/14‬ه ـ واملقيــدة باحملكمــة‬\n‫برقــم ‪ 34643167‬تاريــخ ‪1434/03/15‬ه ـ عليــه افتتحــت اجللســة‬\n‫الســاعة الواحــدة والنصــف وفيهــا حضــر املدعــي العــام (‪ )........‬املعمــد‬\n‫بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب رئيــس دائــرة االدعــاء‬\n‫العــام مبحافظــة األحســاء ذي الرقــم والتاريــخ ‪1433/12/01‬ه ـ وقال يف‬\n‫دعــواه بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام مبحافظــة األحســاء‬\n‫أدعــي علــى (‪ ، )........‬البالــغ مــن العمــر(‪ )37‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )........‬محصــن ‪ ،‬متعلــم ‪ ،‬عســكري‬\n‫باحلــرس الوطنــي ‪ ،‬قبــض عليــه بتاريــخ ‪1433/12/27‬ه ـ صــدر لــه أمــر‬\n‫اإلفــراج الصــادر مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم (ه ـ ق‪ )14337/2/2‬وتاريــخ ‪1434/12/28‬ه ـ اســتناد ًا للمــادة‬\n‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة يســكن محافظــة األحســاء قريــة‬\n‫ال‪ ...‬أنــه بتاريــخ ‪1433/12/27‬ه ـ مت القبــض عليــه مــن قبــل شــرطة‬\n\n                                                                                      ‫‪104‬‬\n\f      ‫ـاء علــى التعميــم الصــادر مــن مركــز شــرطة اجلفــر‬      ‫محافظــة األحســاء بنـ ً‬\n      ‫برقــم (‪/9/21‬ج‪ )8550/‬يف ‪1433/12/26‬ه ـ أثــر تقــدم املواطــن‪... /‬‬\n      ‫بشــكوى مفادهــا قيــام املدعــى عليــه مبعاكســة وإزعــاج زوجتــه عــن‬\n      ‫طريــق رســائل ‪ .........‬مــن اجلــوال رقــم (‪ )...‬وقــد أثبــت محضــر تفريــغ‬\n      ‫الرســائل املرســلة علــى جــوال املجنــي عليهــا ورود عــدة رســائل مــن جــوال‬\n      ‫املدعــى عليــه‪ .‬وباســتجواب املدعــى عليــه ‪ ......‬أقــر مبعاكســته للمجنــي‬\n      ‫عليهــا وإرســاله للرســائل عبــر برنامــج ‪ ......‬وقــد أســفر التحقيــق عــن‬\n      ‫توجيــه االتهــام لــه مبعاكســة إزعاجهــا بالرســائل عبــر جوالــه وذلــك‬\n                                                             ‫لألدلــة والقرائــن التاليــة ‪-:‬‬\n      ‫‪ -1‬مــا جــاء يف إقــراره املــدون علــى الصفحتــن رقــم (‪ )1،2‬مــن دفتــر‬\n                                                       ‫التحقيــق املرفــق لفــة رقــم ( )‬\n      ‫‪ -2‬مــا جــاء يف محضــر تفريــغ الرســائل املــدون علــى الصفحــة رقــم(‪)12‬‬\n                                                      ‫مــن دفتــر االســتدالل لفــة رقــم (‪)1‬‬\n      ‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة‬\n      ‫حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا ـ فعــل محــرم ومعاقــب عليــه شــرع ًا اطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره وبعــرض‬\n      ‫تلــك الدعــوى علــى املدعــى عليــه أجــاب قائــا أصــادق علــى مــا ذكــره‬\n      ‫املدعــي العــام مــن معاكســتي إلحــدى النســاء عــن طريــق هاتــف اجلــوال‬\n      ‫وذلــك بإرســال رســائل لهــا عبــر خدمــة ‪ ......‬وأنــا نــادم علــى ذلــك علم ـ ًا‬\n      ‫بأنــي رجــل متــزوج ولــدي أوالد وكنــت أعمــل برتبــة جنــدي أول وأنــا‬\n      ‫اآلن مفصــول مــن عملــي لــذا وبعــد ســماع الدعــوى و االجابــة وتصفــح‬\n      ‫أوراق املعاملــة وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه‬\n\n\n‫‪105‬‬\n\f‫لقــاء معاكســته إلحــدى النســاء ومجازاتــه لقــاء ذلــك وإن املدعــى عليــه‬\n‫قــد أقــر بذلــك وإن اإلقــرار حجــة شــرعية علــى املقــر وإن مــا أقــدم عليــه‬\n‫املدعــى عليــه حــرام وإجــرام وإن تلــك املــرأة متزوجــة وملــا يف ذلــك مــن‬\n‫إفســاد عالقــة تلــك املــرأة مــع زوجهــا وقــد ورد النــص الشــديد عــن ذلــك‬\n‫ولقولــه عليــه الصــاة والســام (لعــن اهلل مــن خبــب امــرأة علــى زوجهــا)‬\n‫وحلرمــة أعــراض املســلمني و إن أمنهــم محفــوظ والتعــدي عليهــا جرميــة‬\n‫وإن املدعــى عليــه قــد اســتخدم يف جرميتــه هاتــف جــوال ومــن املقــرر‬\n‫شــرع ًا بــأن الوســائل لهــا أحــكام املقاصــد وملشــروعية التعزيــر باملــال‬\n‫وإنــه ال ســوابق علــى املدعــى عليــه لــذا فقــد تقــرر مــا يلــي أوال‪ /‬ثبــوت‬\n‫إدانــة املدعــى عليــه ‪ ...‬لقــاء معاكســته إلحــدى النســاء ومجازاتــه لقــاء‬\n‫ذلــك ولســوابقه بســجنه شــهر ًا يبــدأ مــن تاريــخ إيقافــه بســبب هــذه‬\n‫القضيــة وجلــده ســبعون جلــده مفرقــة علــى فترتــن متســاويتني بينهمــا‬\n‫أســبوعا ثانيــا‪ /‬مصــادرة الهاتــف اجلــوال نــوع ‪ .........‬لــون أبيــض وبيعــه‬\n‫وإيــداع قيمتــه يف خزينــة الدولــة ويصــرف باملصالــح العامــة للدولــة‬\n‫ثالث ـاً‪ /‬إلغــاء خدمــة الشــريحة ذات الرقــم (‪ )...‬الســتخدامه يف عمليــة‬\n‫املعاكســة رابعـاً‪ /‬أخــذ التعهــد الــازم عليــه بعــدم تكــرار مــا بــدر منــه‬\n‫مــرة أخــرى وبذلــك كلــه حكمــت وبعرضــه املدعــى عليــه قناعتــه بــه‬\n‫كمــا أبــدى املدعــي العــام اعتراضــه باحلكــم وطلــب رفعــه حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة وأجيــب لطلبــه واختتمــت اجللســة‬\n‫يف متــام الســاعة الثانيــة ظهــر ًا وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه أجمعــن حــرر يف ‪1434/08/22‬ه ـ ‪.‬‬\n‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n\n\n                                                                                      ‫‪106‬‬\n\f      ‫لــدى احملكمــة برقــم وتاريــخ ‪1434/9/10‬ه ـ الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف الشــيخ ‪/‬د‪ ....‬برقــم‬\n      ‫وتاريــخ ‪1434/9/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه املســجل‬\n      ‫برقــم وتاريــخ ‪1434/8/23‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪.../‬يف‬\n      ‫قضيــة معاكســه وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/19‬ه ـ ‪.‬‬\n\n\n\n\n‫‪107‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":103,"source_page_end":107,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1c95dcc97e312e1c2bddc58e8187bc633ab20369fc6b76ee671cbdef91f89276","normalized_text_hash":"6b2dcd4e45a1c80f33407952b61edd9de9ef171e3a73f0e2e4639e09646bf5da","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p103-34303460"},{"id":"715742f3-eb1f-5784-826f-e6670c0a06bc","document_type":"judgment","category":"judicial","subcategory":"general","title":"حترش -مضايقة امرأة -معاكسة -جتول يف السوق بقصد املعاكسة -إقرار -التعزير باجللد .","document_number":"34218358","case_number":"34124903","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/21","year":"1434","subject":"حترش -مضايقة امرأة -معاكسة -جتول يف السوق بقصد املعاكسة -إقرار -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34218358:‬تاريخه ‪1434/05/21:‬هـ‬\n                    ‫رقم الدعوى ‪34124903:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 34234388:‬تاريخه‪1434/06/07:‬هـ‬\n\n\n ‫حتــرش ‪ -‬مضايقــة امــرأة ‪ -‬معاكســة ‪ -‬جتــول يف الســوق بقصــد‬\n                                  ‫املعاكســة ‪ -‬إقــرار ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n                                              ‫قاعدة (اإلقرار حجة شرعية)‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليهمــا بتجولهمــا يف الســوق بقصــد‬\n ‫معاكســة النســاء وحيــازة كل منهمــا لقصاصــة ورقيــة كتــب فيهــا‬\n ‫رقــم جوالــه لــذات الغــرض ‪ ،‬حيــث إنــه مت القبــض عليهمــا مــن قبــل‬\n ‫هيئــة األمــر باملعــروف والنهــي عــن املنكــر إثــر قيامهمــا بالتجــول يف‬\n ‫الســوق‪ -‬ويكثــران املعاكســة لــكل امــرأة متــر بجوارهمــا ‪ ،‬وبعــد‬\n ‫اســتيقافهما تبــن أنــه قــد جــرى نصحهمــا قبــل ذلــك ‪ ،‬ووجــد مــع كل‬\n ‫منهمــا قصاصــة ورقيــة كتــب فيهــا رقــم جوالــه لــذات الغــرض ‪ ،‬وطلــب‬\n ‫املدعــي العــام تعزيــر املدعــى عليهمــا لذلــك ‪ ،‬أقــر املدعــى عليهمــا مبــا‬\n ‫ـاء علــى مــا تقــدم حكمــت احملكمــة‬     ‫جــاء بدعــوى املدعــي العــام ‪ ،‬بنـ ً‬\n ‫باجللــد وأخــذ التعهــد عليهمــا ‪ ،‬قنــع املدعــى عليهمــا باحلكــم ‪ -‬وقــرر‬\n ‫وصــدق‬‫املدعــي العــام اعتراضــه علــى احلكــم مكتفيـ ًا مبــا جــاء بدعــواه ُ‬\n                                         ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                     ‫‪112‬‬\n\f      ‫اجلزائيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم وتاريــخ ‪1434/03/16‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1434/03/16‬ه ـ حضــر املدعــي‬\n      ‫العــام وادعــى ضــد كال مــن ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )...‬و‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )......‬قائــا‬\n      ‫إنــه بتاريــخ ‪1434/1/22‬ه ـ مت القبــض عليهمــا مــن قبــل رجــال هيئــة‬\n      ‫األمــر باملعــروف والنهــي عــن املنكــر مبحافظــة األحســاء مبركــز‬\n      ‫هيئــة الســوق إثــر قيامهمــا بالتجــول يف الســوق ويكثــران املعاكســة‬\n      ‫بااللتفــات لــكل متســوقة متــر بجوارهمــا وبعــد إســتيقافهما تبــن‬\n      ‫أنــه ســبق منــا نصحهمــا أثنــاء جتولهمــا يف الســوق قبــل بضعــة أيــام‬\n      ‫وبتفتيشــهما ضبــط مــع األول قصاصــة ورقيــة كتــب فيهــا رقــم جوالــه‬\n      ‫كمــا ضبــط مــع الثانــي أيضـ ًا قصاصــة ورقيــة كتــب فيهــا رقــم جوالــه‬\n      ‫وباســتجواب األول أقــر بتجولــه يف الســوق لغــرض املعاكســة وإعــداد‬\n      ‫قصاصــة كتــب فيهــا رقــم جوالــه لــذات الغــرض وباســتجواب الثانــي‬\n      ‫أقــر بتجولــه يف الســوق لغــرض املعاكســة وإعــداد قصاصــة كتــب‬\n      ‫فيهــا رقــم جوالــه لــذات الغــرض وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n      ‫لهمــا بتجولهمــا يف الســوق بقصــد معاكســة النســاء وحيــازة كل منهمــا‬\n      ‫لقصاصــة ورقيــة كتــب فيهــا رقــم جوالــه لــذات الغــرض وذلــك لألدلــة‬\n                                                                 ‫والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬اعترافهمــا مبــا أشــير إليــه املــدون علــى الصفحات رقــم (‪)11،10،9‬‬\n\n‫‪113‬‬\n\f                                           ‫مــن ملــف االســتدالل املرفــق لفــة (‪)1‬‬\n                                      ‫‪ -2‬محضر القبض املرفق لفة رقم ( ‪) 7‬‬\n‫‪ -3‬القصاصــات الورقيــة املرفقــة لفــة رقــم (‪ )6‬وبالبحــث عمــا إذا كان‬\n‫لهمــا ســوابق جنائيــة تبــن خلــو ســجلهما منهــا وحيــث إن مــا أقــدم‬\n‫عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا‬\n‫بعقوبــة تعزيريــة تزجرهمــا وتــردع غيرهمــا لقــاء مــا أســند إليهمــا مــن‬\n‫اتهــام وبعــرض الدعــوى علــى املدعــى عليهمــا أجــاب قائــا أصــادق علــى‬\n‫مــا ذكــره املدعــي العــام مــن دخولــي ســوق النســاء بقصــد املعاكســة‬\n‫كمــا أصــادق علــى حيازتــي لقصاصــة ورقيــة كتــب فيهــا رقــم جوالــي‬\n‫بقصــد املعاكســة وهــذه أول مــره أقــوم بذلــك وأنــا نــادم علــى ذلــك‬\n‫وأضــاف قائــا أننــي متــزوج كمــا أجــاب الثانــي قائــا أصــادق علــى ما‬\n‫ذكــره املدعــي العــام مــن دخولــي ســوق النســاء بقصــد املعاكســة كمــا‬\n‫أصــادق علــى حيازتــي لقصاصــة ورقيــة كتــب فيهــا رقــم جوالــي بقصــد‬\n‫املعاكســة وهــذه أول مــره أقــوم بذلــك وأنــا نــادم علــى ذلــك وأضــاف‬\n‫قائــا أننــي اعــزب لــم يســبق لــي الــزواج لــذا وبعــد ســماع الدعــوى و‬\n‫اإلجابــة وتصفــح أوراق املعاملــة وحيــث طلــب املدعــي العــام إثبــات إدانــة‬\n‫املدعــى عليهمــا لدخولهمــا ســوق النســاء بقصــد املعاكســة وحيازتهمــا‬\n‫لقصاصــات ورقيــه كتــب عليهــا أرقــام جوالتهمــا بقصــد املعاكســة‬\n‫ومجازاتــه لقــاء ذلــك وإن املدعــى عليهمــا قــد أقــرا بذلــك وإن اإلقــرار‬\n‫حجــة شــرعية علــى املقــر وإن ما أقدم عليــه املدعى عليهما حرام وإجرام‬\n‫وحلرمــة أعــراض املســلمني و ان أمنهــم محفــوظ والتعــدي عليهــا جرميــة‬\n‫لــذا فقــد تقــرر مــا يلــي أوال ثبــوت إدانــة املدعــى عليهمــا و لدخولهمــا‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫ســوق النســاء بقصــد املعاكســة وحيازتهمــا لقصاصــات ورقيــه كتــب‬\n      ‫عليهــا أرقــام جوالتهمــا بقصــد املعاكســة ومجازاتهمــا لقــاء ذلــك بجلــد‬\n      ‫كل واحــد منهمــا ثالثــن جلــده ثانيــا أخــذ التعهــد الــازم عليهمــا بعــدم‬\n      ‫تكــرار مــا بــدر منهمــا مــرة أخــرى وبذلــك كلــه حكمــت وبعرضــه‬\n      ‫قــرر املدعــي العــام عــدم قناعتــه بــه وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫مكتفيــا مبــا جــاء يف دعــواه عــن تقــدمي الئحــة اعتراضيــه أمــا املدعــى‬\n      ‫عليهمــا فقــرر قناعتهمــا بــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                              ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/5/20‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم وتاريــخ ‪1434/5/29‬ه ـ الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف الشــيخ‪/‬د‪ ...... .‬برقــم‬\n      ‫وتاريــخ ‪1434/5/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلته املســجل‬\n      ‫كل‬\n       ‫برقــم وتاريــخ ‪1434/5/21‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد ٍ‬\n      ‫مــن‪ ...... /1‬و‪ ...... /2‬يف قضيــة معاكســة وقــد تضمــن القــرار حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n                ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/6/7‬ه ـ ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":112,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95ae24681582bc989161e4ca4f97bd2cc08687658f41792c59979f92ac5f9a05","normalized_text_hash":"8c442bc3e93449b12c095f9e9ae5a9eaf6706692a4a986a00cded0ed82f83de7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p112-34218358"}]$archive_payload$::jsonb AS data)
